  async function discardProfile(){if(saving||!ready)return;if(!await askConfirm('Discard unsaved profile edits and show your last saved profile?'))return;try{localStorage.removeItem(profileDraftKey());profileStorageFailed=false;}catch{$('profileStatus').textContent='Could not remove the draft. Your edits are kept.';return;}profileDirty=false;profileClear=false;renderPlayerProfile();$('profileStatus').textContent='Unsaved edits discarded.';}
  async function clearProfile(){if(saving||!ready)return;if(!await askConfirm('Clear all saved player profile details and self-reported ratings? Your paddles and sessions will remain.'))return;for(const id of Object.values(profileFields))$(id).value='';profileClear=true;captureProfile();await saveProfile();}

  function renderSettings(){renderPlayerProfile();const settings=state.settings??{mainPaddleId:null,overgripHoursPerLevel:4};$('mainPaddleSetting').innerHTML='<option value="">No main paddle</option>'+state.paddles.map(p=>`<option value="${p.id}">${esc(paddleName(p))} — ${esc(p.brand)}</option>`).join('');$('mainPaddleSetting').value=settings.mainPaddleId??'';for(const role of ['singles','doubles','mixed']){const el=$(role+'MainSetting');el.innerHTML=$('mainPaddleSetting').innerHTML;el.value=settings[mainRoles[role]]??'';}$('competitionRulesetSetting').value=settings.competitionRuleset??'usap';$('wearInterval').value=settings.overgripHoursPerLevel;$('edgeWearInterval').value=settings.edgeTapeHoursPerLevel??8;renderGripDate();}
