  function openPaddleForm(){ $('paddleForm').reset();$('paddleOptional').open=false;for(const id of ['photoId','tuningImageId'])$(id).value='';$('catalogModelId').value=''; $('paddleId').value=uid();beginDraft('paddleForm',$('paddleId').value); $('paddleFormTitle').textContent='Add paddle'; $('status').value='active';renderCatalog();renderPhotoPreview(); openModal('paddleModal'); }
