    const setupSnapshot=p=>({weights:p.configuration?.weights??{base:{},items:[]},...Object.fromEntries(setupFields.map(k=>[k,p.configuration?.[k]??''])),notes:p.weightSetup??'',tuningLab:p.configuration?.tuningLab??null});
    if(!old||JSON.stringify(setupSnapshot(p))!==JSON.stringify(setupSnapshot(old))){p.configuration.setupHistory=[...(old?.configuration?.setupHistory??[]),{at:draftMeta.paddleForm?.saveAt??new Date().toISOString(),setup:setupSnapshot(p)}];}
