    if(old&&p.configuration.tuningLab?.reviewedAt!==old.configuration?.tuningLab?.reviewedAt&&p.configuration.tuningLab?.appliedFields?.length)p.measurements=[...(old.measurements??[]),{at:draftMeta.paddleForm?.saveAt??new Date().toISOString(),source:'before_tuning_import',values:Object.fromEntries(p.configuration.tuningLab.appliedFields.map(k=>[k,old[k]??'']))}];
    const measured=['balancePoint','staticWeight','swingWeight','twistWeight','serveSpeed','volleySpeed','weightSetup'];
