    const imageDialog=document.createElement('dialog');imageDialog.id='imageViewer';imageDialog.innerHTML='<div class="sheet-head"><h2>Paddle image</h2><button class="iconbtn" type="button" aria-label="Close image">×</button></div><img alt="Paddle image enlarged"/>';document.body.append(imageDialog);imageDialog.querySelector('button').addEventListener('click',()=>imageDialog.close());document.addEventListener('click',e=>{const b=e.target.closest('[data-view-image]');if(b){imageDialog.querySelector('img').src='/api/photos?id='+encodeURIComponent(b.dataset.viewImage);imageDialog.showModal();}});
