    $('discardPendingPhoto').addEventListener('click',async()=>{if(photoUploading||saving)return;if(await askConfirm('Discard the pending photo upload? Your text and saved photo will remain.')){try{await forgetPhoto(accountId+':'+$('paddleId').value);draftMeta.paddleForm.photoPending=false;captureDraft('paddleForm');$('retryPhoto').hidden=true;$('photoStatus').textContent='Pending photo discarded.';}catch{$('photoStatus').textContent='Could not discard pending photo. Please retry.';}}});
    $('retryPhoto').addEventListener('click',async()=>{try{const file=await pendingPhoto(accountId+':'+$('paddleId').value);if(file)await uploadPhoto({target:{files:[file]}});else $('photoStatus').textContent='Please choose the photo again.';}catch{$('photoStatus').textContent='Photo recovery unavailable. Choose the photo again.';}});
    $('signOut').addEventListener('click',async()=>{document.querySelectorAll('.modal.show form').forEach(f=>captureDraft(f.id));if(saving||photoUploading||draftStorageFailed||profileStorageFailed)return;if(await askConfirm('Sign out? Unfinished drafts and any active timer stay on this device for this account.')){try{if(window.PaddleLogSession)await window.PaddleLogSession.signOut();else location.href='/signout-with-chatgpt?return_to=%2F';analytics?.close();billing?.clear();}catch(e){$('syncStatus').textContent='Could not sign out. '+e.message;}}});
    $('deleteAccount').addEventListener('click',async()=>{if(saving||photoUploading)return;if(!await askConfirm('Permanently delete your PaddleLog account, all paddles, sessions, photos and this device’s drafts? This cannot be undone. Apple subscriptions must be cancelled separately.'))return;try{const {r,d}=await request('/api/account',{method:'DELETE',headers:{'x-confirm-delete':'delete-my-account'}});if(!r.ok)throw new Error(d.error);await clearAccountPhotos(d.accountId);localStorage.removeItem('paddleLog.activeSession.'+d.accountId);localStorage.removeItem('paddleLog.pendingSync.'+d.accountId);localStorage.removeItem('paddleLife.drafts.'+d.accountId);localStorage.removeItem('paddleLog.profileDraft.'+d.accountId);localStorage.removeItem('paddlelog.maintenanceDraft.'+d.accountId);localStorage.removeItem('paddleLog.drafts.v1');if(window.PaddleLogSession)await window.PaddleLogSession.signOut();else location.href='/signout-with-chatgpt?return_to=%2F';}catch(e){$('syncStatus').textContent='Deletion incomplete: '+e.message+' Retry Delete account.';}});
