    document.addEventListener('click',async e=>{const resume=e.target.closest('[data-resume-draft]');if(resume)resumeDraft(resume.dataset.resumeDraft);const discard=e.target.closest('[data-discard-draft]');if(discard&&await askConfirm('Discard this unsaved draft from this device?')){delete drafts[discard.dataset.discardDraft];writeDrafts();renderDrafts();}});
