    window.setInterval(()=>{if(!document.hidden&&!$('viewData').classList.contains('hide')&&!$('settingsAccount').classList.contains('hide'))void refreshHealth();},60000);
    $('loadRecovery').addEventListener('click',async()=>{const target=$('recoveryCopies');target.textContent='Loading recovery copies…';try{const {r,d}=await request('/api/backups');if(!r.ok)throw Error(d.error);target.innerHTML=d.copies.length?d.copies.map(x=>`<button class="btn" type="button" data-recover="${esc(x.id)}">Restore revision ${esc(x.revision)}</button>`).join(''):'No previous saves yet. Recovery copies begin with your next successful save.';}catch(e){target.textContent='Recovery unavailable: '+e.message;}});
    $('recoveryCopies').addEventListener('click',async e=>{const b=e.target.closest('[data-recover]');if(!b)return;try{const {r,d}=await request('/api/backups?id='+encodeURIComponent(b.dataset.recover));if(!r.ok)throw Error(d.error);const recovery=validate(d.state);if(await askConfirm(`Replace your current library with revision ${d.revision}: ${recovery.paddles.length} paddles and ${recovery.sessions.length} sessions? A recovery copy of your current saved library will be kept.`)){state=recovery;const ok=await persist(saved,true);if(ok)$('recoveryCopies').textContent='Library restored. Your previous saved version remains recoverable.';}}catch(e){$('recoveryCopies').textContent='Restore failed: '+e.message+' Your saved library is unchanged.';}});

