    document.addEventListener('change',e=>{if(e.target.matches?.('[data-switch-session-paddle]'))switchActivePaddle(e.target.value);}); $('usageForm').addEventListener('submit', saveUsage);$('estimateForm').addEventListener('submit',saveEstimate);
