    document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;const m=document.querySelector('.modal.show');if(!m)return;if(e.key==='Escape')void cancelModal(m.id);if(e.key==='Tab'){const f=[...m.querySelectorAll('button,input:not([type=hidden]),select,textarea,summary')].filter(x=>!x.disabled&&x.getClientRects().length);const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
